#!/usr/bin/env python3
import csv, gzip, io, json, sys, os
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        raw = f.read()
    if raw[:2] == b'\x1f\x8b':
        raw = gzip.decompress(raw)
    return raw.decode('utf-8-sig').replace('\r\n', '\n').replace('\r', '\n')


def lines_of(path):
    return [l for l in read_text(path).split('\n') if l.strip() != '']


def epoch(dt):
    return int(dt.replace(tzinfo=UTC).timestamp()) if dt.tzinfo is None else int(dt.timestamp())


def local_to_utc(naive, tz, dst=None):
    """naive local datetime -> epoch seconds. dst: None (first occurrence), True/False to pick."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() != b.utcoffset() and dst is not None:
        # ambiguous (fold) or gap
        for c in (a, b):
            if bool(c.dst()) == dst:
                return int(c.timestamp())
    return int(a.timestamp())


def std_offset(tz):
    best = None
    for y in (2026, 2025, 2024):
        for m in (1, 7):
            d = datetime(y, m, 1, tzinfo=tz)
            if not d.dst():
                return d.utcoffset()
            best = best if best is not None else d.utcoffset() - d.dst()
    return best


def parse_offset(s):
    sign = -1 if s[0] == '-' else 1
    return sign * timedelta(hours=int(s[1:3]), minutes=int(s[3:5]))


def norm_dir(s):
    s = s.strip().upper()
    return 'IN' if s in ('IN', 'CLOCK_IN', 'K', 'I') else 'OUT'


# each parser returns list of (id, emp, dir, epoch)
def parse_abbr(path, tz):
    out = []
    header = None
    for row in csv.reader(lines_of(path)):
        if 'Badge' in row and 'Punch' in row:
            header = [c.strip() for c in row]
            continue
        if header is None:
            continue
        r = dict(zip(header, row))
        t = r['Time'].strip()
        ap = None
        parts = t.split()
        if len(parts) == 2:
            t, ap = parts[0], parts[1].upper()
        h, mi, s = (int(x) for x in t.split(':'))
        if ap == 'PM' and h != 12:
            h += 12
        elif ap == 'AM' and h == 12:
            h = 0
        mo, d, y = (int(x) for x in r['Date'].strip().split('/'))
        naive = datetime(y, mo, d, h, mi, s)
        z = r.get('Zone', '').strip().upper()
        dst = True if z.endswith('DT') else False if z.endswith('ST') else None
        out.append((r['Record'].strip(), r['Badge'].strip(), norm_dir(r['Punch']), local_to_utc(naive, tz, dst)))
    return out


def parse_epoch(path, tz):
    out = []
    schema = 1
    for l in lines_of(path):
        o = json.loads(l)
        if 'schema' in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            if 'punch_id' not in o:
                continue
            out.append((str(o['punch_id']), o['employee'], norm_dir(o['direction']), int(o['epoch_ms']) // 1000))
        else:
            if 'id' not in o:
                continue
            ts = int(o['ts']) if 'ts' in o else int(o['ts_ms']) // 1000
            out.append((str(o['id']), o['emp'], norm_dir(o['dir']), ts))
    return out


def parse_offset_csv(path, tz):
    out = []
    ls = lines_of(path)
    rdr = csv.reader(ls, delimiter=';')
    header = None
    for row in rdr:
        if 'punch_id' in row:
            header = row
            continue
        r = dict(zip(header, row))
        ts = datetime.fromisoformat(r['timestamp'].strip())
        out.append((r['punch_id'].strip(), r['employee'].strip(), norm_dir(r['event']), int(ts.timestamp())))
    return out


def parse_legacy(path, tz):
    out = []
    off = None
    std = std_offset(tz)
    for l in lines_of(path):
        t = l[0]
        if t == 'H':
            seg = l[13:18].strip()
            off = parse_offset(seg) if seg else None
        elif t == 'D':
            o = off if off is not None else std
            naive = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            ts = int(naive.replace(tzinfo=UTC).timestamp()) - int(o.total_seconds())
            out.append((l[1:9], 'E' + l[9:15].strip(), norm_dir(l[15]), ts))
    return out


def parse_de(path, tz):
    out = []
    header = None
    for row in csv.reader(lines_of(path), delimiter='\t'):
        if 'Ausweis' in row:
            header = [c.strip() for c in row]
            continue
        r = dict(zip(header, row))
        d, m, y = (int(x) for x in r['Datum'].strip().split('.'))
        hh, mm = (int(x) for x in r['Uhrzeit'].strip().split(':')[:2])
        z = r['Zeitzone'].strip().upper()
        dst = True if z == 'MESZ' else False if z == 'MEZ' else None
        out.append((r['Nr'].strip(), r['Ausweis'].strip(), norm_dir(r['Buchung']),
                    local_to_utc(datetime(y, m, d, hh, mm), tz, dst)))
    return out


def parse_local_csv(path, tz):
