        if 'employee_id' in row:
            header = [c.strip() for c in row]
            continue
        r = dict(zip(header, row))
        naive = datetime.strptime(r['local_time'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((r['punch_ref'].strip(), r['employee_id'].strip(), norm_dir(r['direction']), local_to_utc(naive, tz, None)))
    return out


def parse_local_jsonl(path, tz):
    out = []
    for l in lines_of(path):
        o = json.loads(l)
        p = o.get('punch')
        if not p:
            continue
        naive = datetime.strptime(p['at'].strip(), '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']).strip(), p['badge'], norm_dir(p['type']), local_to_utc(naive, tz, None)))
    return out


