           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_local_csv,
           'local-jsonl': parse_local_jsonl}


def parse_iso_utc(s):
    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    d = datetime.fromisoformat(s)
    if d.tzinfo is None:
        d = d.replace(tzinfo=UTC)
    return d


def main(inp, outfile):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_iso_utc(period['corrections_cutoff'])

    sites = {}
    with open(os.path.join(inp, 'sites.csv'), newline='') as f:
        for r in csv.DictReader(f):
            sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    employees = {}
    with open(os.path.join(inp, 'employees.csv'), newline='') as f:
        for r in csv.DictReader(f):
            employees[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    with open(os.path.join(inp, 'rates.csv'), newline='') as f:
        for r in csv.DictReader(f):
            rates.setdefault(r['employee_id'].strip(), []).append(
                (date.fromisoformat(r['effective_from'].strip()), Fraction(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    # 1. collect
    punches = {}  # (site,id) -> [emp, dir, ts]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                for pid, emp, dr, ts in PARSERS[fmt](os.path.join(root, fn), tz):
                    k = (site, pid)
                    ever.add(k)
                    if k not in punches:
                        punches[k] = [emp, dr, ts]

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for fn in sorted(os.listdir(cdir)):
            p = os.path.join(cdir, fn)
