    corr = [c for c in corr if c[0] <= cutoff]
    corr.sort(key=lambda c: (c[0], c[1]))
    applied = 0
    voided = set()
    for _, _, r in corr:
        k = (r['site'].strip(), r['punch_id'].strip())
        act = r['action'].strip().lower()
        if act == 'void':
            if k in punches:
                del punches[k]
                voided.add(k)
                applied += 1
        elif act == 'set':
            if k in punches:
                punches[k][2] = int(parse_iso_utc(r['time']).timestamp())
                applied += 1
        elif act == 'add':
