            by_emp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, tz):
        off = int(datetime.fromtimestamp(ts, tz).utcoffset().total_seconds())
        loc = ts + off
        r = ((loc + 180) // 360) * 360
        return r - off

    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
