        act = r['action'].strip().lower()
        if act == 'void':
            if k in punches:
                del punches[k]
                voided.add(k)
                applied += 1
        elif act == 'set':
            if k in punches:
                punches[k][2] = int(parse_iso_utc(r['time']).timestamp())
                applied += 1
        elif act == 'add':
            if k not in punches and k not in ever:
                punches[k] = [r['employee'].strip(), norm_dir(r['type']),
                              int(parse_iso_utc(r['time']).timestamp())]
                ever.add(k)
                applied += 1

    by_emp = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in employees:
            by_emp.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(ts, tz):
        off = int(datetime.fromtimestamp(ts, tz).utcoffset().total_seconds())
        loc = ts + off
        r = ((loc + 180) // 360) * 360
        return r - off

    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0))
           for e in employees}

    for emp, plist in by_emp.items():
        hz = sites[employees[emp]][0]

        def workday(ts):
            return datetime.fromtimestamp(ts, hz).date()

        def inper(ts):
            return pstart <= workday(ts) <= pend

        plist.sort()
        kept = []
        last = None
        for ts, _, site, pid, dr in plist:
            if last is not None and last[4] == dr and ts - last[0] <= 300:
                if inper(rnd(ts, sites[site][0])):
                    exc['duplicates_dropped'] += 1
                continue
            last = (ts, 0, site, pid, dr)
            kept.append((rnd(ts, sites[site][0]), site, dr))

        shifts = []
        i = 0
        n = len(kept)
        pending = None
        for ts, site, dr in kept:
            if dr == 'IN':
                if pending is not None and inper(pending[0]):
                    exc['open_shifts'] += 1
                pending = (ts, site)
            else:
                if pending is not None and ts - pending[0] <= 16 * 3600:
                    shifts.append((pending[0], ts, pending[1]))
                    pending = None
                else:
                    if pending is not None and inper(pending[0]):
                        exc['open_shifts'] += 1
                    pending = None
                    if inper(ts):
                        exc['orphan_outs'] += 1
        if pending is not None and inper(pending[0]):
            exc['open_shifts'] += 1

        shifts = [s for s in shifts if inper(s[0])]
        shifts.sort(key=lambda s: s[0])
        day_cum = {}
        week_cum = {}
        total = Fraction(0)
        r = res[emp]
        rl = rates.get(emp, [])
        for a, b, site in shifts:
            wd = workday(a)
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            # night
            tz = sites[site][0]
            night = 0
            cache = {}
            t = a
            while t < b:
                step = min(60, b - t)
                key = t // 900
                if key not in cache:
                    cache[key] = int(datetime.fromtimestamp(t, tz).utcoffset().total_seconds())
                loc = (t + cache[key]) % 86400
                if loc >= 22 * 3600 or loc < 6 * 3600:
                    night += step
                t += step
            night = min(night // 60, paid)
            before = day_cum.get(wd, 0)
            after = before + paid
            day_cum[wd] = after
            dot = max(0, after - 480) - max(0, before - 480)
            wk = wd - timedelta(days=wd.weekday())
            nd = paid - dot
            wb = week_cum.get(wk, 0)
            wa = wb + nd
            week_cum[wk] = wa
            wot = max(0, wa - 2400) - max(0, wb - 2400)
            ot = dot + wot
            reg = paid - ot
            rate = None
            for eff, rv in rl:
                if eff <= wd:
                    rate = rv
            if rate is None and rl:
                rate = rl[0][1]
            if rate is None:
                rate = Fraction(0)
            total += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            r['shifts'] += 1
            r['paid_minutes'] += paid
            r['overtime_minutes'] += ot
            r['night_minutes'] += night
        r['gross'] = total

    def cents(fr):
        c = (fr * 100 + Fraction(1, 2)).__floor__()
        return c

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totc = 0
    for e in sorted(employees):
        r = res[e]
        c = cents(r['gross'])
        totc += c
        for k in tot:
            tot[k] += r[k]
        out_emps[e] = dict(shifts=r['shifts'], paid_minutes=r['paid_minutes'],
                           overtime_minutes=r['overtime_minutes'], night_minutes=r['night_minutes'],
                           gross='%d.%02d' % divmod(c, 100))
    tot['gross'] = '%d.%02d' % divmod(totc, 100)
    with open(outfile, 'w') as f:
        json.dump(dict(period=dict(start=period['start'], end=period['end']), employees=out_emps,
                       exceptions=exc, totals=tot), f, indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
